import React, { useState } from 'react';
import { motion } from 'framer-motion';

export const ClassicToggle = () => {
  const [isOn, setIsOn] = useState(false);
  return (
    <button
      onClick={() => setIsOn(!isOn)}
      className={`relative w-16 h-9 rounded-full p-1 transition-colors duration-300 cursor-pointer border-0 ${isOn ? 'bg-emerald-500' : 'bg-neutral-800'}`}
    >
      <motion.div
        animate={{ x: isOn ? 28 : 0 }}
        transition={{ type: 'spring', stiffness: 500, damping: 30 }}
        className="w-7 h-7 bg-white rounded-full shadow-md"
      />
    </button>
  );
};
